<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {WorkforceApiError} from '../api'
import {usePhasePage} from '../phasePage'
import {attendanceModes,modeLabel,type PolicyPage,type PolicyVersion,type AttendanceMode} from '../attendancePolicy'
import {addDays,storeToday} from '../time'
const props=defineProps<{employeeId?:string}>(),{api,home,store,current,loading,busy,failure,notice,load,english}=usePhasePage()
const data=ref<PolicyPage|null>(null),defaults=ref<PolicyVersion[]>([]),target=ref('employee'),mode=ref<AttendanceMode>('clock'),adopt=ref(false),defaultId=ref(''),date=ref(''),weekdays=ref([1,2,3,4,5]),start=ref('09:00'),minutes=ref<number|null>(480),rest=ref(60),breakOffset=ref(240),leaveMeasurement=ref(false),measurementDraft=ref(false)
const en=computed(()=>english()),id=computed(()=>props.employeeId||home.value?.myself?.id||''),minimum=computed(()=>addDays(data.value?.today||storeToday(),1)),canManage=computed(()=>target.value==='store'?!!home.value?.employeeManage:!!data.value?.canManage),versions=computed(()=>target.value==='store'?defaults.value:data.value?.assignments||[])
const hasArrangement=computed(()=>['clock','default_normal'].includes(mode.value)||leaveMeasurement.value)
function loadDraft(){const policy=versions.value.reduce<PolicyVersion|undefined>((latest,p)=>!latest||p.version>latest.version?p:latest,undefined)||(target.value==='employee'?data.value?.effective:undefined);mode.value=policy?.mode||'clock';const a=policy?.arrangement,optional=['contract','free'].includes(mode.value);measurementDraft.value=!!a;leaveMeasurement.value=!!a&&['contract','free'].includes(mode.value);weekdays.value=a?[...a.weekdays]:optional?[]:[1,2,3,4,5];start.value=a?.startTime||(optional?'':'09:00');minutes.value=a?.standardWorkMinutes??(optional?null:480);rest.value=a?.unpaidBreakMinutes??60;breakOffset.value=a?.unpaidBreakStartOffsetMinutes??240}
function arrangementValid(){return weekdays.value.length>0&&new Set(weekdays.value).size===weekdays.value.length&&weekdays.value.every(d=>Number.isInteger(d)&&d>=1&&d<=7)&&/^([01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(start.value)&&typeof minutes.value==='number'&&Number.isInteger(minutes.value)&&minutes.value>=1&&Number.isInteger(rest.value)&&rest.value>=0&&minutes.value+rest.value<=1440&&(!rest.value||Number.isInteger(breakOffset.value)&&breakOffset.value>=0&&breakOffset.value<=minutes.value)}
watch(leaveMeasurement,enabled=>{if(enabled&&!measurementDraft.value){weekdays.value=[];start.value='';minutes.value=null;measurementDraft.value=true}},{flush:'sync'})
type Pending={path:string;body:unknown};const pending=ref<Pending|null>(null)
function refresh(){void load(async()=>({page:id.value?await api().get<PolicyPage>(props.employeeId?`/employees/${encodeURIComponent(id.value)}/attendance-policy`:'/attendance-policy'):null,defs:home.value?.employeeManage?await api().get<PolicyVersion[]>('/attendance-policy-defaults'):[]}),v=>{data.value=v.page;defaults.value=v.defs;defaultId.value=v.defs.at(-1)?.id||'';if(!id.value||!v.page?.canManage&&home.value?.employeeManage)target.value='store';date.value=versions.value.reduce((d,p)=>p.effectiveFrom>=d?addDays(p.effectiveFrom,1):d,minimum.value);loadDraft()})}
async function send(){if(!pending.value||busy.value)return;busy.value=true;failure.value='';const shop=store.value,client=api();try{await client.put(pending.value.path,pending.value.body);if(!current()||shop!==store.value)return;pending.value=null;notice.value=en.value?'Saved':'已保存';refresh()}catch(e){if(e instanceof WorkforceApiError&&e.status<500)pending.value=null;if(current()&&shop===store.value)failure.value=en.value?'Unable to save. Retry the original request or reload after resolving a conflict.':'保存失败；可重试原请求，冲突时重新加载。'}finally{if(current()&&shop===store.value)busy.value=false}}
function save(){if(!canManage.value||pending.value)return;const adopting=target.value==='employee'&&adopt.value;if(date.value<versions.value.reduce((d,p)=>p.effectiveFrom>=d?addDays(p.effectiveFrom,1):d,minimum.value)||!adopting&&hasArrangement.value&&!arrangementValid()){failure.value=en.value?'Check effective date, working weekdays and the explicit measurement arrangement':'请检查生效日期、工作日及明确的计量安排';return}const body={expectedVersion:Math.max(0,...versions.value.map(v=>v.version)),effectiveFrom:date.value,...(adopting?{adoptDefault:true,defaultId:defaultId.value}:{mode:mode.value,arrangement:hasArrangement.value?{weekdays:weekdays.value,startTime:start.value,standardWorkMinutes:minutes.value,unpaidBreakMinutes:rest.value,unpaidBreakStartOffsetMinutes:rest.value?breakOffset.value:null}:null,...(target.value==='employee'?{adoptDefault:false}:{})})};pending.value={path:target.value==='store'?`/attendance-policy-defaults/${crypto.randomUUID()}`:`/employees/${encodeURIComponent(id.value)}/attendance-policies/${crypto.randomUUID()}`,body:JSON.parse(JSON.stringify(body))};void send()}
watch(target,()=>{loadDraft();date.value=versions.value.reduce((d,p)=>p.effectiveFrom>=d?addDays(p.effectiveFrom,1):d,minimum.value)})
onMounted(refresh)
</script>
<template><section><h3>{{en?'Attendance policy':'考勤计薪方式'}}</h3><p class="wf-hint">{{en?'Independent of clock location. Store defaults are adopted explicitly as dated snapshots. Changes start tomorrow at the earliest.':'独立于打卡位置。门店默认须显式采用，保存日期及来源快照；最早次日生效。'}}</p><p v-if="loading" role="status">{{en?'Loading…':'加载中…'}}</p><p v-if="failure" role="alert" class="wf-error">{{failure}}</p><p v-if="notice" role="status">{{notice}}</p><button v-if="failure&&!pending" @click="refresh">{{en?'Retry':'重试'}}</button><p v-if="data?.effective"><strong>{{en?'Current':'当前执行'}}: {{modeLabel(data.effective.mode,en)}}</strong> · {{data.effective.timezone}}</p>
<form v-if="canManage&&!loading" @submit.prevent="save"><fieldset :disabled="busy||!!pending"><div class="wf-grid"><label v-if="id">{{en?'Scope':'设置范围'}}<select v-model="target"><option value="employee" :disabled="!data?.canManage">{{en?'Employee':'当前员工'}}</option><option v-if="home?.employeeManage" value="store">{{en?'Store default':'门店默认'}}</option></select></label><label>{{en?'Effective date':'生效日期'}}<input v-model="date" type="date" :min="minimum" required></label></div><label v-if="target==='employee'" class="wf-check"><input v-model="adopt" type="checkbox">{{en?'Adopt a dated store default snapshot':'显式采用门店默认快照（解除个人覆盖）'}}</label><label v-if="adopt&&target==='employee'">{{en?'Default version':'默认版本'}}<select v-model="defaultId" required><option value="">{{en?'Select':'请选择'}}</option><option v-for="d in defaults" :key="d.id" :value="d.id">{{d.effectiveFrom}} · {{modeLabel(d.mode,en)}} · v{{d.version}}</option></select></label><template v-else><label>{{en?'Mode':'方式'}}<select v-model="mode"><option v-for="m in attendanceModes" :key="m" :value="m">{{modeLabel(m,en)}}</option></select></label><label v-if="mode==='contract'||mode==='free'" class="wf-check"><input v-model="leaveMeasurement" type="checkbox" data-field="leaveMeasurement">{{en?'Leave measurement arrangement (optional)':'请假计量安排（可选）'}}</label><p v-if="mode==='contract'||mode==='free'" class="wf-hint">{{en?'Used only to measure leave intervals. This does not create attendance hours or require clocking. Leave it off when no explicit arrangement exists. Enter weekdays, start time and net minutes explicitly; no hours are inferred from a contract or a standard day.':'仅用于请假区间计量，不产生出勤工时、不要求打卡；没有明确安排时保持关闭；启用后须明确填写工作日、起点及净分钟，不从合同或通用8小时推定。'}}</p><template v-if="hasArrangement"><fieldset class="wf-weekdays"><legend>{{en?'Working weekdays (Monday = 1)':'固定工作日（周一为1）'}}</legend><label v-for="day in 7" :key="day" class="wf-check"><input v-model="weekdays" type="checkbox" :value="day">{{day}}</label></fieldset><div class="wf-grid"><label>{{en?'Start time':'开始时间'}}<input v-model="start" type="time" required></label><label>{{en?'Net work minutes':'净工作分钟'}}<input v-model.number="minutes" type="number" min="1" :max="1440-rest" required></label><label>{{en?'Unpaid break minutes':'无薪休息分钟'}}<input v-model.number="rest" type="number" min="0" :max="1440-(minutes??0)" required></label><label v-if="rest>0">{{en?'Break start offset from work start (minutes)':'休息开始距上班分钟'}}<input v-model.number="breakOffset" type="number" min="0" :max="minutes??0" required></label></div></template></template><footer class="wf-form-actions"><button class="primary">{{en?'Save future policy':'保存未来策略'}}</button></footer></fieldset></form><button v-if="pending" :disabled="busy" @click="send">{{en?'Retry original request':'重试原请求'}}</button><details><summary>{{en?'Policy history':'策略历史'}}</summary><p v-for="v in versions" :key="v.id">{{v.effectiveFrom}} · {{modeLabel(v.mode,en)}} · v{{v.version}} · {{v.origin==='adopted_default'?(en?'Adopted default snapshot':'已采用默认快照'):v.origin==='personal'?(en?'Personal':'个人覆盖'):(en?'Store default':'门店默认')}}</p><p v-if="!versions.length">{{en?'No records':'暂无记录'}}</p></details></section></template>
